function IconArt({ kind }: { kind: NewsItem['icon'] }) {
  const Icon = kind === 'landmark' ? Landmark : kind === 'shield' ? ShieldCheck : HeartHandshake
  return <div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-white/80 text-suara-teal shadow-sm"><Icon size={24}/></div>
}
function Button({ children, onClick, variant = 'primary', className = '', type = 'button', disabled = false }: { children: React.ReactNode; onClick?: () => void; variant?: 'primary' | 'secondary' | 'ghost' | 'light'; className?: string; type?: 'button' | 'submit'; disabled?: boolean }) {
  const base = 'inline-flex items-center justify-center gap-2 rounded-xl px-4 py-3 text-sm font-semibold transition focus-visible:outline-none disabled:cursor-not-allowed disabled:opacity-50'
  const styles = { primary: 'bg-suara-teal text-white hover:bg-suara-deep shadow-sm', secondary: 'border border-emerald-100 bg-white text-suara-deep hover:bg-suara-mint', ghost: 'text-suara-teal hover:bg-suara-mint', light: 'bg-white text-suara-deep hover:bg-emerald-50' }
  return <button type={type} disabled={disabled} onClick={onClick} className={`${base} ${styles[variant]} ${className}`}>{children}</button>
}
function SectionHeading({ eyebrow, title, text }: { eyebrow?: string; title: string; text?: string }) {
  return <div className="mb-5"><div className="mb-2 text-xs font-bold uppercase tracking-[.16em] text-suara-teal">{eyebrow}</div><h2 className="text-2xl font-extrabold tracking-tight text-suara-deep sm:text-3xl">{title}</h2>{text && <p className="mt-2 max-w-2xl text-sm leading-6 text-slate-600">{text}</p>}</div>
}
function NewsCard({ item, onOpen, featured = false }: { item: NewsItem; onOpen: (id: number) => void; featured?: boolean }) {
  return <article className={`flex h-full flex-col overflow-hidden rounded-3xl border border-emerald-50 bg-white shadow-soft ${featured ? 'w-[300px] shrink-0 sm:w-[350px]' : ''}`}>
    <div className={`news-image relative flex h-44 items-start justify-between overflow-hidden bg-gradient-to-br ${item.theme} p-5`}>
      <img src={newsImage(item.id)} alt={`Ilustrasi berita: ${item.category}`} className="absolute inset-0 h-full w-full object-cover" loading="lazy" onError={e => { e.currentTarget.style.display = 'none' }}/>
      <div className="absolute inset-0 bg-gradient-to-t from-[#102f2a]/85 via-[#102f2a]/15 to-[#102f2a]/10" />
      <span className="relative rounded-full border border-white/30 bg-white/85 px-3 py-1.5 text-[11px] font-bold text-suara-deep backdrop-blur">{item.category}</span>
      <span className="absolute bottom-4 left-5 rounded-full border border-white/25 bg-black/20 px-2.5 py-1 text-[10px] font-semibold tracking-wide text-white backdrop-blur">ILUSTRASI · {item.source}</span>
      <div className="absolute right-4 top-4 rounded-full border border-white/25 bg-white/20 p-2 text-white backdrop-blur"><ArrowUpRight size={16}/></div>
    </div>
    <div className="flex flex-1 flex-col p-5">
      <div className="mb-3 flex items-center gap-1.5 text-xs text-slate-500"><CalendarDays size={13}/>{item.date}</div>
      <h3 className="line-clamp-3 text-base font-bold leading-6 text-suara-deep">{item.headline}</h3>
      <p className="mt-3 line-clamp-3 flex-1 text-sm leading-6 text-slate-600">{item.summary}</p>
      <Button onClick={() => onOpen(item.id)} className="mt-5 w-full">Baca Berita <ArrowUpRight size={16}/></Button>
    </div>
  </article>
}
function AnalysisCard({ a }: { a: Analysis }) {
  return <section className="rounded-2xl border border-emerald-100 bg-white p-5 shadow-sm sm:p-6">
    <div className="flex flex-wrap items-start justify-between gap-3"><div><div className="text-xs font-bold uppercase tracking-wider text-suara-teal">Relevansi konstitusional</div><h3 className="mt-1 text-lg font-extrabold text-suara-deep">{a.article}</h3><p className="mt-1 font-semibold text-slate-700">{a.label}</p></div><span className="max-w-full rounded-full bg-amber-50 px-3 py-1.5 text-xs font-semibold leading-5 text-amber-800">{a.status}</span></div>
    <div className="mt-5 space-y-4 text-sm leading-6">
      <div><h4 className="font-bold text-suara-deep">Inti pasal</h4><p className="mt-1 text-slate-600">{a.summary}</p></div>
      <div><h4 className="font-bold text-suara-deep">Makna sederhana</h4><p className="mt-1 text-slate-600">{a.meaning}</p></div>
      <div><h4 className="font-bold text-suara-deep">Kaitan dengan kasus</h4><p className="mt-1 text-slate-600">{a.connection}</p></div>
      <div><h4 className="font-bold text-suara-deep">Mengapa hak ini penting?</h4><p className="mt-1 text-slate-600">{a.importance}</p></div>
      <div><h4 className="font-bold text-suara-deep">Tanggung jawab</h4><p className="mt-1 text-slate-600">{a.responsibility}</p></div>
    </div>
  </section>
}
